// Commentators on romans 1: guzik = Enduring Word (Arabic), mac = John MacArthur sermons; sources in data/sources/commentary.json
// guzik: David Guzik, Enduring Word (Arabic); mac: John MacArthur sermons. Sections and sermons: data/sources/commentary.json; reading notes: data/sources/guzik, data/sources/mac
// piper: John Piper sermons (desiringGod.org), id in data/sources/commentary.json; reading notes in data/sources/piper/romans-1.md
export default [
{ r: '1', k: 'guzik', sec: 'A1', p: 'يذكر جوزيك أن سيرة بولس معروفة من سفر الأعمال وغلاطية ١ و٢ كو ١١-١٢، ويرجح أنه كتب الرسالة من كورنثوس في رحلته الثالثة (أع ٢٠: ٢-٣؛ رو ١٦: ١، ٢٣). وكانت الرسالة عوضا عن زيارة تأخرت، فأراد أن يصل إنجيله إلى رومية ولو لم يصل هو. وكلمة "عبد" (دولوس) تعني عنده، كما ينقل عن موريس، التكريس الكامل للسيد لا المذلة، ويرى بولي أن هذا اللقب أرفع من أي لقب ملكي. أما "المفرز" فيربطها كلارك بماضي بولس الفريسي، فالفريسي "منفصل"، لكنه صار الآن مفرزا لإنجيل الله لا لتقاليد الناس.' },
  { r: '1', k: 'guzik', sec: 'I1', p: 'يفتتح جوزيك تفسيره بأثر هذه الرسالة في التاريخ: أغسطينوس اهتدى حين قرأ رو ١٣: ١٣-١٤، ولوثر وجد في رو ١: ١٧ أن بر الله يعطى بالإيمان فشعر كأنه ولد من جديد، وويسلي تدفأ قلبه وهو يسمع مقدمة لوثر لرومية. وينقل عن كالفن أن من فهم هذه الرسالة انفتح له الطريق إلى فهم الكتاب كله، وعن جوديه أنها كاتدرائية الإيمان المسيحي. ويذكر بكلام بطرس أن في رسائل بولس أمورا عسرة الفهم (٢بط ٣: ١٥-١٦)، فالرسالة تحتاج إلى جهد وصبر.' },
  { r: '2', k: 'guzik', sec: 'A2', p: 'يؤكد جوزيك أن الإنجيل الذي يحمله بولس ليس اختراعا جديدا، بل هو ما سبق الله فوعد به بأنبيائه في الكتب المقدسة. فالبشارة امتداد لعمل الله في العهد القديم لا قطيعة معه. وينبه إلى أن موريس يحصي ورود كلمة "الله" في الرسالة ١٥٣ مرة، وهو أعلى تكرار في العهد الجديد، فرومية في جوهرها رسالة عن الله وخطته للفداء.' },
  { r: '3-4', k: 'guzik', sec: 'A2', p: 'يجعل جوزيك المسيح مركز الإنجيل: هو من نسل داود من جهة الجسد، أي الملك الموعود، وهو ابن الله الذي أعلن بقوة بالقيامة. وكلمة "تعين" (هوريزو) معناها التحديد والتمييز، ويذكر كلارك أن منها كلمة "الأفق"، أي إظهار واضح لا يحتمل الشك. ويربط القيامة بقول المسيح عن هيكل جسده أنه يقيمه (يو ٢: ١٩). وينقل عن موريس أن لقب "ربنا" يقابل اسم يهوه في الترجمة اليونانية للعهد القديم، فهو إعلان لألوهية المسيح.' },
  { r: '5-6', k: 'guzik', sec: 'A2', p: 'يقول جوزيك إن الإنجيل يحمل معه نعمة ورسالة، وغايته "إطاعة الإيمان في جميع الأمم". فالإيمان الحقيقي يظهر في الطاعة، والرسالة موجهة إلى الأمم كلها، ومنهم المؤمنون في رومية الذين هم أيضا "مدعوو يسوع المسيح".' },
  { r: '7', k: 'guzik', sec: 'A3', p: 'يذكر جوزيك أن بولس لم يؤسس كنيسة رومية ولم يزرها، وربما نشأت من يهود ودخلاء رجعوا من يوم الخمسين (أع ٢: ١٠)، ولا دليل على أن بطرس أسسها. ويرى أنهم "أحباء الله" و"مدعوون قديسين"، وينقل عن سبرجن أنهم صاروا قديسين بالدعوة لا قبلها. والتحية تجمع "النعمة" وهي تحية يونانية و"السلام" وهي تحية يهودية، وكلاهما من الله الآب والرب يسوع المسيح معا.' },
  { r: '8-10', k: 'guzik', sec: 'A3', p: 'يلاحظ جوزيك أن بولس يشكر الله على إيمان الرومانيين الذي ذاع في العالم، وينقل عن بروس أن الكنيسة هناك كانت تحت ضغط واضطهاد وصور مشوهة عنها في زمن نيرون، ومع ذلك اشتهر إيمانها. ثم يتوقف عند صلاة بولس الدائمة لأجلهم، وينقل عن سبرجن أن الكنيسة تزدهر حين يذكرها أبناؤها في الصلاة بلا انقطاع.' },
  { r: '11-12', k: 'guzik', sec: 'A3', p: 'يرى جوزيك أن شوق بولس إلى رومية لم يكن رغبة في أن يأخذ بل في أن يعطي "هبة روحية" ليثبتهم، ومع ذلك يتواضع فيجعل التعزية متبادلة: إيمانه وإيمانهم معا. وقد منعته ظروف كثيرة من المجيء، لكن رغبته في التشجيع المتبادل بقيت.' },
  { r: '13-15', k: 'guzik', sec: 'A3', p: 'يفسر جوزيك قول بولس "إني مديون" بأنه شعر بدين لرومية التي أعطت العالم سلاما ونظاما وطرقا وثقافة، ووفاء الدين أن يعطيها الإنجيل. وكلمة "مستعد" يشرحها بأمثلة يجمعها سبرجن من حياة بولس: مستعد للخدمة (رو ١٥: ١)، وللآلام (أع ٢١: ١٣)، وللمهام الصعبة (٢كو ٦: ١٠)، وللموت (٢تي ٤: ٦)، ويروي قصة زنزندورف عن مرسل كان مستعدا للذهاب فورا. وينقل عن نيويل إعجابه بجرأة بولس، ويلاحظ مع سبرجن أن بولس وصل إلى رومية أسيرا لا كما تمنى.' },
  { r: '16', k: 'guzik', sec: 'A4', p: 'يرى جوزيك مع موريس أن الآيتين ١٦-١٧ قصيرتان لكنهما مفتاح الرسالة. فرومية التي سماها سينيكا "بالوعة الإثم" ووصفها يوفينال بالمجرى القذر كانت تفتخر بالقوة، وبولس يعلن أن عنده قوة أعظم: الإنجيل قوة الله للخلاص لكل من يؤمن، لليهودي أولا ثم لليوناني. ويذكر أن فلاسفة ذلك الزمان مثل أبكتيتوس وأبيقور وسينيكا أدركوا أن الإنسان يحتاج إلى علاج وخلاص، وقدم كل منهم دواءه، لكن الإنجيل وحده قوة الله.' },
  { r: '17', k: 'guzik', sec: 'A4', p: 'يشرح جوزيك أن فعل "يبرر" (ديكايوو) معناه، كما ينقل عن باركلي، أن الله يعامل الخاطئ كأنه لم يخطئ. وينقل عن لينسكي أن أعظم يوم في حياة لوثر كان حين فهم أن "بر الله" هو حكم الله بالبر على المؤمن، وعن موراي أن بر الله هو البر الذي يبرر، المتميز بكمال الله نفسه. وعبارة "بإيمان لإيمان" يفهمها بولي بمعنى "بالإيمان وحده"، ويرى هاريسون أن التبرير بالإيمان بداية الحياة المسيحية لا نهايتها (غل ٣: ١-٣). والشاهد هو حبقوق: "البار بالإيمان يحيا" (حب ٢: ٤).' },
  { r: '18', k: 'guzik', sec: 'B1', p: 'يقول جوزيك إن أعظم خطر يواجه البشر هو غضب الله المعلن من السماء. والناس يسيئون فهم الغضب لأنهم يقيسونه على غضب الإنسان الأناني، أما غضب الله فقدوس كامل. وينقل عن موراي أن الغضب نفور مقدس في كيان الله من كل ما يضاد قداسته، وعن موريس أن الخلاص لا معنى له إن لم يكن هناك شيء نخلص منه. فالآية ليست بشارة في ذاتها، بل تبين حاجة الإنسان المطلقة إلى الإنجيل المذكور في ١: ١٦. ويفرق بين "الفجور" وهو الخطية ضد الله، و"الإثم" وهو الخطية ضد الآخرين، ويرى أن الناس "يحجزون" الحق عمدا.' },
  { r: '19-20', k: 'guzik', sec: 'B2', p: 'يعلم جوزيك أن صفات الله غير المنظورة، أي قدرته السرمدية ولاهوته، ترى بوضوح في الخليقة، ولذلك صار الناس "بلا عذر". وينقل عن لينسكي أن أحدا لا يستطيع أن يلوم الله كأنه أخفى نفسه، فلا عذر لعدم الإيمان. فالمشكلة ليست نقص المعرفة بل رفض المعرفة المعطاة.' },
  { r: '21-23', k: 'guzik', sec: 'B2', p: 'يرى جوزيك أن الناس عرفوا الله لكنهم لم يمجدوه ولم يشكروه، فحمقت أفكارهم وأظلم قلبهم. وينقل عن سبرجن أن معرفة الله بلا تمجيده لا تنفع شيئا حتى للاهوتيين، وأن الشكر أمر جوهري، ويضرب مثلا بالشكر على وجبة بسيطة. ورفض الله لا يجعل الإنسان أحكم، بل يقوده إلى الخداع وإظلام القلب، وهذا الإظلام نفسه جزء من دينونة الله. وكلمة "شبه صورة" (إيكون) تحذر من خطر استبدال مجد الله بصورة يختارها الإنسان لنفسه من البشر والطيور والدواب والزحافات.' },
  { r: '24-25', k: 'guzik', sec: 'B3', p: 'يلاحظ جوزيك أن عبارة "أسلمهم الله" تتكرر ثلاث مرات (٢٤، ٢٦، ٢٨): إلى شهوات قلوبهم، وإلى أهواء الهوان، وإلى ذهن مرفوض. وهذه هي دينونة الله: أن يترك الناس يذوقون النتائج المدمرة لخطيتهم، كما قيل عن أفرايم: "اتركوه" (هو ٤: ١٧). وفي الآية ٢٥ يلاحظ أداة التعريف في "الكذب"، فهو الكذبة الأصلية، أي العبادة الوثنية ووهم أن يصير الإنسان كالله، فعبد الناس المخلوق دون الخالق.' },
  { r: '26-27', k: 'guzik', sec: 'B3', p: 'يذكر جوزيك أن بولس كتب من كورنثوس المعروفة بفسادها الجنسي، ويرى أن كلمة "كذلك" في الآية ٢٧ تربط الممارسة المثلية عند النساء والرجال معا، وأن بولس استعمل لفظي "الذكور" و"الإناث" العامين. ويصف عادات المجتمع الروماني وسلوك نيرون خلفية للنص. ويلاحظ أن الخطية تحمل جزاءها في ذاتها، كما قال بولس: "نائلين في أنفسهم جزاء ضلالهم".' },
  { r: '28-32', k: 'guzik', sec: 'B3', p: 'يشرح جوزيك أن "الذهن المرفوض" هو الذهن الذي سقط في الامتحان كالعملة المزيفة، وينقل عن ويست أن الناس امتحنوا الله فلما لم يوافق مقاييسهم رفضوه، فأسلمهم إلى ذهن مرفوض. وفي قائمة الخطايا (٢٩-٣١) ينبه إلى أن خطايا يقبلها المجتمع كالكبرياء والحسد تقف جنبا إلى جنب مع القتل، ويذكر أن الحسد هو الذي أسلم يسوع للصلب (مت ٢٧: ١٨). وينقل عن كلارك أن "النمامين" مشتكون في السر يهدمون السمعة، وأن "المتعظمين" يرفعون أنفسهم فوق غيرهم. والذروة في الآية ٣٢: يعرفون حكم الله أن فاعلي هذه يستوجبون الموت، ومع ذلك يفعلونها ويسرون بالذين يعملون.' },
  { r: '1', k: 'mac', ser: '45-01', p: 'يبدأ ماك آرثر سلسلته بأثر رومية في تاريخ الكنيسة: أغسطينوس ولوثر وويسلي تغيروا بها، ومفتاحها رو ١: ١٧. ثم يرسم صورة بولس: نشأ في طرسوس وتتلمذ لغمالائيل، وكان فريسيا غيورا اضطهد الكنيسة (أع ٨: ١-٣؛ في ٣: ٥)، ويشبه فعل "يسطو" في أع ٨: ٣ بخنزير بري يعيث في كرم. ثم تغير على طريق دمشق (أع ٩: ٣-٦، ٢٠) ودعي رسولا للأمم (أع ١٣: ١-٣). ويعدد أغراض الرسالة: أن يزورهم ويثبتهم ويربح نفوسا ويطلب صلواتهم ويستعد للذهاب إلى إسبانيا (رو ١: ١١، ١٥؛ ١٥: ٢٨-٣٢). ويلاحظ أن الرسالة تقتبس العهد القديم نحو ٥٧ مرة، أكثرها من إشعياء.' },
  { r: '8-10', k: 'mac', ser: '45-05', p: 'يرى ماك آرثر أن بولس يفتح قلبه قبل أن يشرح الإنجيل، ليبين أن الخدمة الحقيقية تخرج من الداخل لا من الواجب الخارجي. فأول علامة روح شاكرة: يشكر "إلهي بيسوع المسيح" على إيمانهم بدل أن يتملقهم، وكان يشكر بينما يتآمر عليه اليهود في كورنثوس (أع ٢٠: ٢-٣). والثانية روح مصلية: الفعل "أعبده" (لاتريو) يستعمل للعبادة الموجهة إلى الله، فخدمته عبادة قلبية (رو ١٢: ١؛ في ٣: ٣)، وصلاته "بلا انقطاع" (١تس ٥: ١٧؛ أف ٦: ١٨). والثالثة روح مستعدة: يطلب أن يذهب إليهم "بمشيئة الله"، مستعدا أن يكون هو جواب صلاته كما قال إشعياء: "هأنذا أرسلني" (إش ٦: ٨).' },
  { r: '13-15', k: 'mac', ser: '45-07', p: 'يتابع ماك آرثر علامات الخدمة الروحية. في الآية ١٣ روح مثمرة: عبارة "لست أريد أن تجهلوا" تنبه إلى حق جوهري، والثمر عنده موقف داخلي (غل ٥: ٢٢-٢٣) وعمل صالح (رو ٦: ٢٢) ونفوس تضاف إلى الجسد (رو ١٦: ٥). وفي الآية ١٤ روح مطيعة: بولس مديون لليونانيين والبرابرة والحكماء والجهلاء، ويشرح أن كلمة "بربري" مأخوذة من صوت كلام غير مفهوم "بر بر". وفي الآية ١٥ روح متحمسة، فهو "مقيد بالروح" (أع ٢٠: ٢٢) ومستعد أن ينفق وينفق (٢كو ١٢: ١٥؛ ١كو ٩: ١٦-١٧).' },
  { r: '16', k: 'mac', ser: '45-07', p: 'يختم ماك آرثر علامات الخدمة بالروح الجريئة: "لست أستحي بإنجيل المسيح". وينقل عن جفري ولسون قوله إن الإنجيل الذي لا يزعج أحدا إنجيل لا يعمل شيئا، ويستشهد بكلمة الشهيد باسيليوس: "لي الحياة هي المسيح والموت هو ربح" (في ١: ٢١)، وبقول وليم لويد جاريسون إنه لن يراوغ ولن يعتذر. فالخادم الحقيقي لا يخجل من رسالة يراها العالم جهالة.' },
  { r: '16', k: 'mac', ser: '45-08', p: 'يرى ماك آرثر أن الآيتين ١٦-١٧ تلخصان الرسالة كلها في أربع كلمات: قوة، خلاص، إيمان، بر. فالقوة (ديناميس) هي قدرة الله التي تلد الإنسان من جديد، لأن الإنسان عاجز عن تغيير نفسه، "هل يغير الكوشي جلده؟" (إر ١٣: ٢٣؛ رو ٥: ٦؛ يع ١: ١٨). والصليب جهالة عند العالم لكنه قوة الله (١كو ١: ١٨، ٢٣؛ ٢: ٢-٥). والخلاص نجاة من الخطية والشيطان والدينونة والموت. والإيمان ثقة بالمسيح لا عضوية كنسية ولا معمودية ولا أخلاق (أف ٢: ٨-٩). وينقل عن روبرت هالدين أن "لليهودي أولا" لأن اليهود شعب الله القديم وأول من بشروا. ويذكر سخرية كلسس من المسيحيين الذين يعبدون ميتا.' },
  { r: '17', k: 'mac', ser: '45-08', p: 'يشرح ماك آرثر أن "بر الله" المعلن في الإنجيل بر يعطى للمؤمن ولا يكتسب، لأن المسيح حمل خطيته: "جعل الذي لم يعرف خطية خطية لأجلنا لنصير نحن بر الله فيه" (٢كو ٥: ٢١؛ رو ٣: ٢١-٢٢؛ ٤: ٣؛ في ٣: ٨-٩). وعبارة "بإيمان لإيمان" يفهمها بأن الإنجيل يمتد إلى إيمان كل من يؤمن. والأساس من العهد القديم: "البار بالإيمان يحيا" (حب ٢: ٤). ويروي أن المرسل جون باتون ترجم فعل الإيمان في يو ٣: ١٦ بعبارة من لغة أهل الجزيرة معناها "يلقي بثقله كله عليه".' },
  { r: '18', k: 'mac', ser: '45-09', p: 'يقول ماك آرثر إن الغضب نقطة انطلاق الإنجيل: الدينونة هي التشخيص والنعمة هي العلاج، ولذلك يبدأ القسم ١: ١٨-٣: ٢٠ بإدانة البشر جميعا. والكلمة "غضب" (أورجي) سخط عميق ثابت لا ثورة انفعال، والفعل "معلن" (أبوكاليبتو) في المضارع، أي أنه ينكشف باستمرار. ويفرق بين "الفجور" (أسيبيا) أي عدم توقير الله، و"الإثم" (أديكيا) أي الظلم في معاملة الناس النابع منه. ويستشهد بالعهد القديم: "الله يسخط كل يوم" (مز ٧: ١١)، و"عيناك أطهر من أن تنظرا الشر" (حب ١: ١٣)، ومع يو ٣: ٣٦ وأف ٢: ١-٣. وينقل عن بارنهاوس تشبيه الغضب بخزان ماء خلف سد، انفتح على المسيح في الجلجثة.' },
  { r: '19-20', k: 'mac', ser: '45-10', p: 'يرى ماك آرثر أن الآيتين تبرران الغضب بالإعلان: "معرفة الله" (غنوستوس، أي ما يمكن معرفته) ظاهرة فيهم، فلا يستطيع أحد أن يدعي الجهل. وهذا إعلان طبيعي في الخليقة: قدرة الله السرمدية ولاهوته ترى بالمصنوعات، والتصميم يدل على مصمم، فهم "بلا عذر". ويربط ذلك بالمزامير: "السماوات تحدث بمجد الله" (مز ١٩؛ مز ٩٤: ٩)، وبكلام بولس في لسترة وأثينا (أع ١٤: ١٥-١٧؛ ١٧: ٢٣-٢٧) ويو ١: ٩. وينقل عن أغسطس سترونج وهودج أن الله لم يترك نفسه بلا شاهد، وعن ترتليان أن الطبيعة تعلم النفس، ويذكر قول الفلكي روبرت جاسترو إن علم الفلك يشير إلى علة لا يستطيع العلم تسميتها.' },
  { r: '21', k: 'mac', ser: '45-11', p: 'يرسم ماك آرثر سقوط الإنسان في أربع مراحل: إعلان، رفض، تبرير ذاتي، دين. والآية ٢١ هي الرفض: "لم يمجدوه كإله"، والمجد هو صفات الله نفسه، وحرمانه من مجده أخطر خطية. ويتتبع خيط المجد في الكتاب: آدم يختبئ (تك ٣: ٨)، وموسى يرى المجد (خر ٣٣-٣٤)، والمجد يملأ الهيكل (١مل ٨: ١٠) ثم يرحل بسبب الأصنام (حز ٨)، ثم يحل في المسيح (يو ١: ١٤). ويذكر هيرودس الذي ضرب لأنه لم يعط المجد لله (أع ١٢: ٢١-٢٣)، وينقل عن توري أن النظرة الضعيفة إلى الدينونة تأتي من نظرة سطحية إلى الخطية وقداسة الله.' },
  { r: '22', k: 'mac', ser: '45-12', p: 'الآية ٢٢ عند ماك آرثر هي مرحلة التبرير الذاتي: رفض الناس الإعلان ثم ادعوا الحكمة، و"صاروا جهلاء" من الفعل موراينو الذي منه كلمة "أبله" بالإنجليزية. والظلمة جهل عقلي وانحراف أخلاقي معا. ويحذر من الفلسفة المضادة للإنجيل (كو ٢: ٨) ويذكر أن الله يبيد حكمة الحكماء (إش ٢٩: ١٤؛ ١كو ١: ١٩). وينقل عن مارتن لويد جونز أن الحداثة في الكنيسة بدأت حين تحول الناس من الإعلان إلى الفلسفة. ويمثل بنبوخذنصر الذي افتخر فأذل ثم مجد الله (دا ٤)، وبيشوع الذي قال لعخان: "أعط الآن مجدا للرب" (يش ٧: ١٩).' },
  { r: '24-25', k: 'mac', ser: '45-14', p: 'يلاحظ ماك آرثر أن "أسلمهم الله" تتكرر ثلاث مرات (٢٤، ٢٦، ٢٨)، والفعل باراديدومي يستعمل للتسليم إلى القضاء أو السجن (مت ٤: ١٢؛ ٥: ٢٥؛ ١٨: ٣٤). فالله يرفع يد الردع، والخطية الناتجة هي نفسها تعبير عن غضبه الحاضر (١: ١٨). وكلمة "النجاسة" (أكاثارسيا) نجاسة داخلية جنسية خاصة، تخرج من القلب (مر ٧: ٢١-٢٣؛ إر ١٧: ٩؛ أم ٤: ٢٣). ويستشهد بالعهد القديم: "لا يدين روحي في الإنسان إلى الأبد" (تك ٦: ٣)، و"فسلمتهم إلى قساوة قلوبهم" (مز ٨١: ١١-١٢؛ هو ٤: ١٧). وفي الآية ٢٥ استبدلوا حق الله بالكذب وعبدوا المخلوق دون الخالق. وينقل عن سي إس لويس من كتابه "مشكلة الألم".' },
  { r: '1', k: 'piper', ser: 'the-author-of-the-greatest-letter-ever-written', p: 'يفتتح بايبر سلسلته في رومية بقصته الشخصية مع هذه الرسالة: يرجح أنه آمن طفلا نحو سنة ١٩٥٢، ثم فهم لاحقا من رومية ما حدث له، ويذكر خطوات البشارة التي تعلمها منها (رو ٣: ٢٣؛ ٦: ٢٣؛ ٥: ٨؛ ١٠: ٩). ويروي كيف ثبت كتاب جون ستوت عن رومية ٥-٨ دعوته للخدمة، وكيف شكلت دراسة رومية ١-١١ مع دانيال فولر فهمه لسيادة الله ومجده كغاية الخليقة، وكيف قاده صراعه مع رومية ٩ إلى الرعاية. ثم يقول إن سؤال الآية الأولى ليس "من أنا؟" بل "لمن أنا؟". فبولس "عبد" للمسيح، أي مملوك له بالشراء وتحت سلطانه (١كو ٧: ٢٣؛ غل ١: ١٠)، والمسيح الذي مات حي ويملك عليه. ويقابل ذلك بمن يعيشون ليرضوا الناس ويستمدوا قيمتهم من نظرة غيرهم. والتطبيق أن المؤمن مملوك لله مرتين، بالخلق وبالفداء، فحياته كلها موجهة لإرضاء المسيح وتعظيمه.' },
  { r: '1', k: 'piper', ser: 'the-author-of-the-greatest-letter-ever-written', p: 'يشرح بايبر "المدعو رسولا": الرسول كان يجب أن يرى المسيح المقام وأن يكلفه المسيح نفسه (١كو ١٥: ٧-٨؛ أع ٢٦: ١٦). ولذلك فالأساس الرسولي للكنيسة (أف ٢: ٢٠) لا يتكرر، والكنيسة اليوم مبنية على تعليم الرسل المكتوب، ورومية في قلبه. ثم "المفرز لإنجيل الله": الله أفرز بولس من بطن أمه (غل ١: ١٥) مع أنه صار مضطهدا للكنيسة (١تي ١: ١٦)، وهذا عند بايبر إعلان للنعمة السيادية المجانية التي لا تنتظر استحقاقا. ويربط ذلك بذروة الرسالة في رو ١١: ٣٣-٣٦، حيث كل الأشياء منه وبه وله. وينقل عن ليون موريس أن الله مذكور في الرسالة نحو ١٦٠ مرة، فرومية كتاب عن الله قبل أن تكون عن الإنسان. والخلاصة أن الله هو أساس حياة بولس ومركزها وغايتها.' },
  { r: '2', k: 'piper', ser: 'gods-good-news-concerning-his-son', p: 'يقول بايبر إن الإنجيل ليس دينا جديدا بل تحقيق لوعود قديمة، فالله سبق فوعد به في الكتب. وهذا يقوي الإيمان: إله يحفظ وعوده عبر القرون يمكن الاتكال عليه في وعوده لنا. ويتوقف عند حرف الجر: الله وعد "بأنبيائه"، أي من خلالهم، فالمتكلم الحقيقي هو الله والأنبياء أدواته. ولهذا سميت الكتب "مقدسة"، لأن الله يتكلم فيها، ويربط ذلك بأف ٢: ٢٠ و١كو ٢: ١٣ و٢بط ٣: ١٦ حيث كلام الرسل أيضا من الله. والعقيدة هنا هي وحي الكتاب وسلطانه. والتطبيق أن يعامل الكتاب ككلمة الله نفسها، فيشكل الوعظ والعبادة والعقيدة.' },
  { r: '3', k: 'piper', ser: 'gods-good-news-concerning-his-son', p: 'يلاحظ بايبر أن الإنجيل "عن ابنه"، والابن كان موجودا قبل أن يصير إنسانا، فبنوته فريدة تختلف عن بنوة المؤمنين لله (رو ٨: ١٤، ١٩). ويؤكد أن المسيح إله كامل (رو ٩: ٥؛ كو ٢: ٩)، وأنه أخذ طبيعة بشرية ووُلد من نسل داود. وهذا تحقيق للوعود المسيانية بالملك من بيت داود (إر ٢٣: ٥؛ إش ١١: ١٠؛ ٩: ٦-٧)، فكل مواعيد الله فيه "نعم" (٢كو ١: ٢٠). ومع مجيء ابن داود جاء الملكوت ومعه البر والسلام والفرح (مر ١: ١٤-١٥؛ إش ٣٥: ١٠). والعقيدة التي يبرزها: طبيعتان في المسيح، إلهية وبشرية، وملكه المسياني.' },
  { r: '4', k: 'piper', ser: 'gods-good-news-concerning-his-son', p: 'يقول بايبر إن بين الآية ٣ والآية ٤ حدثا مسكوتا عنه: الابن مات. وكان هذا صادما لمن انتظروا مسيا منتصرا (لو ٢٤: ٢١)، لأن المسيا في ظنهم لا يموت. ثم جاءت القيامة، وهي قلب الإنجيل. ويرى أن الروح القدس كان شريكا في إقامة المسيح (رو ٨: ١١)، ويقترح أن عبارة "روح القداسة" ربما تقابل بين قداسة الروح وبين الاتصال النجس بالموتى، كما فعل شاول مع صاحبة الجان (١صم ٢٨). وكلمة "تعين" يمكن أن تعني "أقيم" أو "عين"، و"بقوة" تصف البنوة نفسها: لم يصر ابنا بالقيامة، بل انتقل من الاتضاع إلى ابن الله في القوة. وهو الآن يملك وسيخضع كل أعدائه (مت ٢٨: ١٨؛ ١كو ١٥: ٢٥-٢٦؛ في ٢: ١١). والتطبيق أن نعيش في رجاء ملكه الظاهر قائلين: آمين، تعال أيها الرب يسوع.' },
  { r: '5', k: 'piper', ser: 'by-his-grace-for-his-name-through-the-obedience-of-faith', p: 'يقول بايبر إن كلمة النعمة ترد في العهد الجديد ١٥٥ مرة، منها ٢٤ في رومية، وهي في قلب الإنجيل وصفات الله. والنعمة تأتي "به"، أي بيسوع المسيح، فهي قائمة على طاعته وموته (رو ٣: ٢٤-٢٥؛ ٥: ١٨-٢١)، وليست حقا لنا بل اقتناها لنا آخر. ثم يلاحظ أن النعمة هنا مقرونة بالرسالة، فهي ليست غفرانا فقط بل قوة تمكن من الخدمة (رو ١٢: ٣، ٦؛ ١٥: ١٥-١٦). والنعمة لا تدفع كأجرة (رو ٤: ٤؛ ١١: ٦)، بل تقبل بالإيمان لكي تبقى مجانية (رو ٤: ١٦)، وهي "تملك" كملك (رو ٥: ٢١). والمسيح هو الذي يعمل بواسطة بولس (رو ١٥: ١٨؛ ١كو ١٥: ١٠). والتطبيق الجميل عنده: ضع دعوتك أنت مكان كلمة "رسالة"، معلما كنت أو طالبا أو أما أو أرملة، فكل دعوة تعاش بالنعمة لا بالاعتماد على النفس.' },
  { r: '5', k: 'piper', ser: 'by-his-grace-for-his-name-through-the-obedience-of-faith', p: 'يعرض بايبر قراءتين لعبارة "إطاعة الإيمان": الطاعة التي تنبع من الإيمان، أو الطاعة التي هي الإيمان نفسه كاستجابة لأمر الإنجيل. ويميل إلى الجمع بينهما، ويذكر اعتراض ليون موريس بأن بولس لو قصد الإيمان وحده لما احتاج إلى كلمة الطاعة. ويستشهد بأن المحبة تخرج من إيمان (١تي ١: ٥)، وبأن الطاعة بالإيمان لا بالأعمال (رو ٩: ٣٢)، وبأن كل ما ليس من الإيمان فهو خطية (رو ١٤: ٢٣). فالمنطق عنده: النعمة تمكن الطاعة، والإيمان يستقبل النعمة، فالطاعة ثمرة الإيمان. ثم "لأجل اسمه": غاية عمل الله أن يعرف اسمه ويحب ويمجد، كما أقام فرعون ليُخبر باسمه في كل الأرض (رو ٩: ١٧)، والمعطي ينال المجد (١بط ٤: ١١). ويجيب عن سؤال: هل طلب الله لمجده محبة؟ نعم، لأن من يدعو باسم الرب يخلص (رو ١٠: ١٣)، ولأننا نفتخر على رجاء مجد الله (رو ٥: ٢)، فمجده هو غاية أشواقنا.' },
  { r: '6-7', k: 'piper', ser: 'the-called-of-christ-and-the-loved-of-god-part-1', p: 'يلاحظ بايبر أن بولس يعرّف نفسه والقراء بما عمله الله لهم لا بإنجازاتهم: هو عبد ورسول بالنعمة، وهم "مدعوو يسوع المسيح" و"أحباء الله". ويقابل بين كنيسة صغيرة في رومية وإمبراطورية هائلة، ويقول إن دعوة الله لأفراد قد تكون أعظم في الأبدية من كل أحداث السياسة العالمية. ثم يشرح أن الخلاص ليس "ديمقراطية" فيها حقوق متساوية، فالقلب ميت ومظلم (أف ٤: ١٨)، ولا أحد له حق على الله، والله يرحم من يرحم (رو ٩: ١٥). ويثبت ثلاث حقائق: الله هو الداعي، فالدعوة إلى شركة ابنه (١كو ١: ٩)؛ والدعوة خاصة بالبعض (رو ٨: ٢٨، ٣٠)؛ والدعوة فعالة تخلق ما تأمر به. ويفرق بين الدعوة العامة للإنجيل الموجهة للجميع (مر ٤: ١٤؛ أع ١٧: ٣٠؛ مت ٢٢: ١٤) والدعوة الفعالة التي تجعل المسيح المصلوب قوة الله وحكمته في عيون المدعوين (١كو ١: ٢٣-٢٤). و"مدعوين قديسين" تعني أن القداسة نفسها ثمرة الدعوة.' },
  { r: '6-7', k: 'piper', ser: 'the-called-of-christ-and-the-loved-of-god-part-2', p: 'يشرح بايبر أن الإيمان يحتاج إلى أمرين معا: شاهد بشري يكرز بالمسيح (٢كو ٤: ٥)، ونور إلهي يشرق في القلب كما قال الله في الخليقة ليشرق نور من ظلمة (٢كو ٤: ٦)، لأن إله هذا الدهر أعمى الأذهان (٢كو ٤: ٤). فالدعوة الفعالة مثل نداء يسوع للعازر (يو ١١: ٤٣): كلمة تقيم الميت. ثم ينتقل إلى "أحباء الله"، ويفرق بين محبة عامة يرسل بها الله الشمس والمطر على الجميع ويقدم ابنه لكل من يؤمن (مت ٥: ٤٤-٤٥؛ يو ٣: ١٦)، ومحبة عهدية خاصة للمدعوين. ويشبهها برسالة يكتبها لزوجته "حبيبتي نويل"، فهي محبة اختيار وعهد لا مودة عامة. وأساسها العهد الجديد (إر ٣١: ٣١) الذي يعد فيه الله ألا يرجع عن شعبه وأن يجعل مخافته في قلوبهم فلا يحيدوا (إر ٣٢: ٤٠)، وقد ختم بدم المسيح (لو ٢٢: ٢٠). ولذلك لا يقدر شيء أن يفصل المدعوين عن محبة الله (رو ٨: ٣٠-٣٩)، وهذا هو قلب يقين المؤمن.' },
  { r: '8', k: 'piper', ser: 'the-treasure-of-faith-in-the-life-of-the-church', p: 'يرى بايبر أن الأصحاح يبين بولس وهو يعيش رسالته المعلنة في الآية ٥، أي إطاعة الإيمان لأجل اسم المسيح. فهو يشكر الله لا المؤمنين على إيمانهم، لأن الإيمان عطية من الله (أف ٢: ٨-٩)، فنشكر عليه ولا نفتخر به. والإيمان عنده ليس سلعة مجردة بل ثقة أشخاص، وهو غير منظور لكنه يظهر في الطاعة، كما تعرف الشجرة من ثمرها، ولذلك صار إيمانهم معروفا في كل العالم. ويقول إن الإيمان يمجد الله مرتين: كمعطيه، وبإظهار أنه أهل للثقة (رو ٤: ٢٠-٢١). والتطبيق أن نشكر الله على إيمان الآخرين بدل أن ننسبه لهم أو لأنفسنا.' },
  { r: '9-12', k: 'piper', ser: 'the-treasure-of-faith-in-the-life-of-the-church', p: 'يفهم بايبر عبارة "أعبده بروحي" على أنها الخدمة الخفية في الصلاة، لا الكرازة العلنية وحدها، فبولس يشهد الله على صلاته المستمرة لأجلهم. وعبارة "بمشيئة الله" تعني أن توقيت الزيارة في يد الله السيد. أما هدف الزيارة فأن يمنحهم هبة روحية "لثباتهم"، أي ليتقوى إيمانهم، ويربط ذلك بإرسال تيموثاوس ليثبت أهل تسالونيكي (١تس ٣: ٢). والعقيدة هنا أن الطاعة تحتاج إلى إيمان قوي تنبع منه، والصلاة هي اتكال على الله ليتمم مقاصده. ثم يلاحظ تواضع بولس: هو أيضا ينتظر أن يتعزى بإيمانهم، فالتشجيع متبادل. والتطبيق أن نصلي بلا انقطاع لنمو إيمان الآخرين، ونتوقع أن نُبنى نحن أيضا ونحن نبني غيرنا.' },
  { r: '11-12', k: 'piper', ser: 'the-gospel-in-the-church-for-the-obedience-of-faith-through-spiritual-gifts', p: 'يستخرج بايبر من رغبة بولس في أن يمنح هبة روحية، ومن تعزيته المتبادلة معهم، أن الخدمة لا تقوم على واعظ واحد. فكل مؤمن وكيل على نعمة الله المتنوعة ويخدم بالموهبة التي أخذها (١بط ٤: ١٠)، والمواهب تختلف بحسب النعمة المعطاة (رو ١٢: ٦-٨). والمواهب عنده أشكال من النعمة هدفها بناء الجسد لإطاعة الإيمان. وإذا كان الرسول نفسه يحتاج أن يتعزى بإيمان المؤمنين العاديين، فلا أحد في الكنيسة مستغن عن الآخرين. والتطبيق العملي عنده أن المجموعات الصغيرة هي المكان الأساسي الذي يستعمل فيه المؤمنون مواهبهم ويشجع بعضهم بعضا.' },
  { r: '13', k: 'piper', ser: 'the-treasure-of-faith-in-the-life-of-the-church', p: 'يلاحظ بايبر أن بولس قصد مرارا أن يأتي إلى رومية ومُنع، وهدفه أن يكون له "ثمر" فيهم كما في سائر الأمم. والثمر عنده هو نفسه إطاعة الإيمان المذكورة في الآية ٥. ويستعين بقول بولس في رو ٦: ٢٢ أن المؤمنين صار لهم ثمرهم للقداسة والنهاية حياة أبدية، فالثمر هو النتيجة المنظورة للتقديس. والتطبيق أن نطلب في الناس طاعة منظورة نامية لا مجرد اعتقاد خاص. ويجمع بايبر الآيات ٨-١٥ في غاية واحدة: الشكر والصلاة والرغبة في الثمر كلها تخدم إطاعة الإيمان لمجد الله، وهذه عنده رسالة الكنيسة في الحي وبين الأمم.' },
  { r: '14', k: 'piper', ser: 'the-gospel-in-the-church-for-the-obedience-of-faith-through-spiritual-gifts', p: 'يتوقف بايبر عند كلمة "مديون"، ويقول إن الترجمة الحرفية تحتفظ بها. ويسأل: لمن الدين؟ ويجيب أنه للناس لا لله، لأن النعمة لا تخلق دينا نسدده لله كقرض، فالعطية التي يحاول الإنسان أن يدفع ثمنها تصير شراء لا هبة. أما ديننا لله فهو دين السرقة، لأننا سرقنا مجده واستبدلناه بأشياء أقل (رو ١: ٢٣؛ ٣: ٢٣)، وهذا جوهر الخطية، والنعمة تسدده (مت ٦: ١٢). فمن نال نعمة صار مديونا بها لكل من يحتاجها، كمن سمع خبرا سارا عن النجاة من بلية مشتركة فيجب أن يخبر الآخرين. والثقافة والذكاء لا تؤهل أحدا، وغيابها لا يحرم أحدا، فبولس نفسه لم يكن مؤهلا والنعمة ما زالت تأتيه (١كو ١٥: ١٠). ويطبق ذلك على العنصرية والكلمات العرقية المهينة والبر الذاتي والتطلب في الزواج، لأن حجب النعمة عن غيرنا إنكار لأنها نعمة.' },
  { r: '15', k: 'piper', ser: 'the-gospel-in-the-church-for-the-obedience-of-faith-through-spiritual-gifts', p: 'يلفت بايبر إلى أن بولس مستعد أن يبشر "الذين في رومية"، أي المؤمنين أنفسهم، لا غير المؤمنين فقط. والسبب أن الإنجيل لا يأتي بالناس إلى الإيمان فحسب، بل يحفظهم ويقدسهم. ويربط ذلك بقول بولس إنه كتب إليهم ليذكرهم ويخدم الإنجيل لكي يكون قربان الأمم مقدسا (رو ١٥: ١٥-١٦)، وبإنجيل نعمة الله الذي حمله (أع ٢٠: ٢٤)، وبأن الإيمان بالخبر (رو ١٠: ١٧). فالمعادلة عنده: الإيمان يتغذى على النعمة، والطاعة تتغذى على الإيمان. والتطبيق أن المؤمنين يحتاجون أن يسمعوا إنجيل النعمة مرة بعد مرة طوال حياتهم.' },
  { r: '16', k: 'piper', ser: 'not-ashamed-of-the-gospel', p: 'يعتبر بايبر الآية ١٦ أطروحة الرسالة كلها، ويربطها بما قبلها: بولس مستعد أن يبشر في رومية لأنه لا يستحي. ثم يحلل الخزي بأربع قصص من الحياة: ولد يخسر سباقا أمام طفل جديد تفاخر بأنه سيغلبه، وطالب سخر من زميل أبوه مسجون ثم قبض على أبيه هو، وشخص يذهب إلى حفل بلباس غير مناسب بسبب نصيحة خاطئة، وممثل ينسى سطرين على المسرح. والقاسم المشترك أننا نريد دائما أن نبدو جيدين ونتجنب ما يسيء إلى صورتنا. أما بولس فلم يهرب من الخزي: ضُرب وسُجن وغرق (٢كو ١١: ٢٣-٢٦)، والإنجيل كان عند اليهود عثرة وعند اليونانيين جهالة (١كو ١: ٢٢-٢٣). ويقول إن الإنجيل يعرضنا للخزي أولا ثم يحررنا منه.' },
  { r: '16', k: 'piper', ser: 'not-ashamed-of-the-gospel', p: 'يرى بايبر أن مفتاح تحرر بولس من الخزي هو مثال يسوع الذي احتمل الصليب مستهينا بالخزي من أجل السرور الموضوع أمامه (عب ١٢: ٢). فيسوع تُرك واستهزئ به وعُري وعذب، لكنه نظر إلى ما بعد الخزي، إلى جلوسه عن يمين الله. وبولس سار على هذا النمط: وثق في قوة الله ومجده الآتي أكثر من ظروفه الحاضرة. ثم يطبق ذلك على عصرنا: الناس اليوم قلما يقولون إن الإنجيل كاذب، بل يقولون إن ادعاء أي حق ديني غرور وتعصب. والجواب ليس التراجع بل قول الحق عن الخلاص بمحبة، لأن المسيح وحده هو الطريق (يو ١٤: ٦) وليس بأحد غيره الخلاص (أع ٤: ١٢). وبهذا نسدد الدين الذي علينا للعالم دون أن نخضع للخزي.' },
  { r: '16', k: 'piper', ser: 'the-gospel-is-the-power-of-god-unto-salvation', p: 'يفرق بايبر بين أن يُخزى المؤمن من الناس، وهذا متوقع، وبين أن يستحي هو بالإنجيل، وهذا غير لازم. ثم يسأل: ما "الخلاص" هنا؟ الإنجيل يحول الناس فعلا بسماع الكلمة (رو ١٠: ١٧؛ ١بط ١: ٢٣-٢٥؛ أف ٢: ٨-٩)، لكنه يرى أن بولس يقصد أساسا الخلاص النهائي: قوة الله التي توصل المؤمنين إلى الأمان والفرح الأبديين. ويقدم أربعة أسباب: أولا، أديان كثيرة تكسب أتباعا، فمجرد التحويل لا يرفع الخزي، أما الإنجيل فيخلص أتباعه إلى النهاية. ثانيا، بولس يستعمل كلمة الخلاص كثيرا بمعنى مستقبلي (٢تس ٢: ١٣؛ ٢كو ٧: ١٠؛ عب ٩: ٢٨؛ ١بط ١: ٥؛ رو ٥: ٩-١٠؛ ١٣: ١١). ثالثا، فعل "يؤمن" في المضارع اليوناني يدل على إيمان مستمر، فالخلاص لمن يثبت مؤمنا (١كو ١٥: ١-٢؛ يع ٢: ١٧، ٢٦). رابعا، بولس يكتب إلى مؤمنين (رو ١: ١٥). والتطبيق أن نتغذى يوميا على وعود الإنجيل مثل رو ٨: ٣٢ لنحارب اليأس والكبرياء والطمع والشهوة.' },
  { r: '16-17', k: 'piper', ser: 'how-does-the-gospel-save-believers', p: 'يسأل بايبر: كيف يخلص الإنجيل من هم مؤمنون بالفعل؟ ويجيب أولا: مم نخلص؟ والجواب الأساسي في رومية هو غضب الله (رو ١: ١٨؛ ٢: ٥، ٨؛ ٥: ٩)، فالإنجيل في جوهره خبر أن الله نفسه أنقذنا من غضب الله. ثم يقرأ الآية ١٧ قراءة خاطئة عمدا: "لأن فيه معلن محبة الله"، ليبين أن بولس لم يقل ذلك، لأن محبة الله ليست عاطفة تتجاهل الخطية، بل حكيمة عادلة تعالج الإثم والغضب (رو ٥: ٨). والحل الذي تعلنه الآية: الله يطلب برا ليس عندنا، ورجاؤنا الوحيد أن يعطينا هو البر الذي يطلبه. ويذكر قصة لوثر الذي كره عبارة "بر الله" حتى فهم أنها البر الذي به يبرر الله الرحيم الإنسان بالإيمان، فشعر أنه ولد من جديد. والتطبيق أن ندرس رومية بجد، لا أن نكتفي بعنوانها، استعدادا لساعة الموت والوقوف أمام الديان.' },
  { r: '17', k: 'piper', ser: 'how-does-the-gospel-save-believers-part-2', p: 'يعرض بايبر ثلاثة معان ممكنة لعبارة "بر الله": إظهار عدل الله في معاقبة الخطية في المسيح البديل، أو المكانة البارة التي يعلنها الله للخاطئ المغفور له بالاحتساب، أو التغيير الأخلاقي الذي يجعل المؤمن أكثر طاعة. ويقول إن الثلاثة صحيحة وكلها عطايا الإنجيل، لكن المعنى الأساسي في هذه الآية هو الثاني، أي البر المحسوب. وحجته الأولى من اقتباس حبقوق: البر في أول الآية لله، وفي الاقتباس للإنسان البار، وهذا لا يستقيم إلا إذا حسب الله بره للإنسان. ويلاحظ أن "البر" و"البار" من جذر يوناني واحد. وحجته الثانية التوازي مع رو ٣: ٢٠-٢٦: البر "المعلن" هنا هو البر "الظاهر" هناك بدون الناموس، والكلام هناك صريح عن التبرير مجانا بالنعمة. وحجته الثالثة أن المعاني الأخرى تلتقي معه، فالله بار ويبرر (٣: ٢٥-٢٦)، والصليب يثمر طاعة بالروح (٨: ٣-٤). والتطبيق: كف عن الاتكال على أدائك واسترح في بر المسيح، وارجع إلى الإنجيل كل يوم.' },
  { r: '17', k: 'piper', ser: 'how-does-the-gospel-save-believers-part-3', p: 'يرجع بايبر إلى سياق حبقوق: الله يقيم الكلدانيين للقضاء (حب ١: ٥-٦)، وعيناه أطهر من أن تنظرا الشر (١: ١٣)، فالسؤال: كيف ينجو إنسان من دينونة الله؟ والجواب أن البار بالإيمان يحيا، أي ينجو من القضاء. ومن هنا يستنتج أن الخاطئ لا يقف أمام الله القدوس باستحقاقه، فالبر الذي يحيا به عطية تنال بالإيمان. أما عبارة "بإيمان لإيمان" فيقرؤها في ضوء ٢كو ٢: ١٥-١٦ (من موت لموت ومن حياة لحياة)، ويشبه الإيمان بنافذة: الإيمان الأول يدخل نور بر الله، والبر المعلن يوقظ إيمانا أكثر ويحفظه. ويربط ذلك بأن الخلاص مستقبلي مؤسس على تبرير ماض (رو ١٣: ١١؛ ٥: ٩؛ ٨: ٣٠، ٣٢)، فالبر يحسب أولا ثم يُعمل فينا تدريجيا. والإيمان المخلص هو الذي يثبت (١كو ١٥: ١-٢؛ مر ١٣: ١٣؛ كو ١: ٢٣؛ ١بط ١: ٥؛ رو ٨: ١٣). والتطبيق أن نطيع لا لنكسب القبول، بل لأن الذنب رُفع والبر أُعطي، فنحارب الخطية كخطاة مبررين.' },
  { r: '18', k: 'piper', ser: 'the-wrath-of-god-against-ungodliness-and-unrighteousness', p: 'يبدأ بايبر بكلمة "لأن" التي تربط الآية ١٨ بالآية ١٧، فكل كلام بولس عن الخطية في خدمة الإنجيل، والقسم من ١: ١٨ إلى ٣: ٢٠ يصف حال الأمم ثم اليهود ثم الجميع. ويلاحظ أن "معلن" هنا هو الفعل نفسه وبالزمن نفسه كما في الآية ١٧، فالغضب يعلن الآن، في هذا الدهر، مع أن يوم الغضب الأخير آت (٢: ٥، ٨-٩؛ ٥: ٩). ويذكر ثلاثة إعلانات حاضرة للغضب: الموت الشامل كدينونة بسبب معصية آدم (٥: ١٥-١٨)، وإخضاع الخليقة للبطل على رجاء (٨: ١٨-٢١؛ تك ٣: ١٥)، وتسليم الناس إلى خطاياهم (١: ٢٤، ٢٦، ٢٨). لكن الغضب ممتزج بالرحمة، فالله يرسل الشمس والمطر ويعطي خيرات (مت ٥: ٤٥؛ أع ١٤: ١٧)، ولطفه يقتاد إلى التوبة (رو ٢: ٤-٥)، فهو يتكلم بلغتين: الإنذار في الألم والجذب في اللذة. أما للمؤمن فلا دينونة (٨: ١)، والموت صار بابا، والألم تطهيرا (٨: ٢٨؛ عب ١٢)، والخطية خُلعت عن عرشها (رو ٦). والتطبيق: لا تهرب من دراسة الخطية، لأن فهمها يعمق محبتك للإنجيل.' },
  { r: '18', k: 'piper', ser: 'the-wrath-of-god-against-holding-down-the-truth', p: 'يربط بايبر "حجز الحق" بما يسميه ثقافة "تجميل الوقائع": كلنا بطبيعتنا نلطف أسماء خطايانا ونقسو في الحكم على غيرنا (رو ٢: ١)، ونراوغ ونلوم ونتهرب حين يواجهنا الحق. وهذا ليس وصفا لفئة سيئة بل للبشر جميعا بدون النعمة (٣: ٩-١٠، ١٣). والحق المحجوز هو ما يعلنه الخلق: أن الله موجود وخالق، قادر أزلي مكتف بذاته، ونحن مدينون له بالشكر ومخلوقون لإظهار مجده (١: ١٩-٢١، ٢٥، ٢٨؛ مز ٥٠: ٢٣)، فنحن نأخذ البركات وهو يأخذ المجد. ويشرح لماذا يذكر بولس الشكر لا الإيمان هنا: الإيمان يستجيب لوعود محددة تأتي بالإعلان الخاص في الكتاب (رو ٤: ٢٠)، أما الشكر فيطلبه الإعلان الطبيعي من الجميع. وعبارة "بالإثم" تعني أن الحجز ينبع من محبة الخطية (٢تس ٢: ١٠-١٢؛ يو ٣: ١٩-٢١). فالمشكلة أخلاقية قبل أن تكون عقلية، والقلب قبل الرأس، والعلاج ليس معلومات أكثر بل قلب جديد. والتطبيق: افحص ميلك لتجميل خطاياك، واطلب قلبا جديدا، وعش شاكرا، وتوكل على بر المسيح.' },
  { r: '19-20', k: 'piper', ser: 'displays-of-god-remove-the-excuse-for-failed-worship', p: 'يجيب بايبر عن سؤال: ماذا عن الذين لم يسمعوا؟ ويتتبع حجة بولس من نهايتها: هم "بلا عذر" (قارن ٢: ١١-١٦)، لأنهم لم يمجدوا الله ولم يشكروه، مع أنهم عرفوه، لأن الله نفسه أظهر لهم ما يعرف عنه. ويلاحظ أن العبارة اليونانية "ظاهرة فيهم" تحمل معنى "بينهم". والمعروف هو قدرته السرمدية ولاهوته، ظاهرين منذ خلق العالم. ويتوقف عند كلمة "المصنوعات" (بويما) التي منها كلمة "قصيدة" في الإنجليزية: القصيدة تدل على قصد وتصميم وحكمة، والريح التي ترسم حروفا على الرمل لا تكتب قصيدة، والكون قصيدة عن الله، صنعها من العدم. ثم يطبق ذلك على العلم، ويرى أن التطور الطبيعي المحض افتراض فلسفي يحجب التصميم، ويذكر كتابات فيليب جونسون ومايكل بيهي (مثال سوط البكتيريا ذي التعقيد غير القابل للاختزال) وويليام دمبسكي. والتطبيق في خدمة المدينة: كل إنسان يعرف الله في داخله، فهناك أرض مشتركة، وأعظم مأساة في المدينة ليست المخدرات والفقر بل أن يهلك الناس بلا عذر، والإنجيل هو أقوى استراتيجية.' },
  { r: '21', k: 'piper', ser: 'the-first-dark-exchange-idolatry', p: 'يرى بايبر أن بولس يسمي المشكلة الأساسية للإنسان مرتين قبل قائمة الخطايا: لم يمجدوا الله (آية ٢١)، وأبدلوا مجده (آية ٢٣). فمجد الله هو الحقيقة الموحدة للكتاب والكون، وشر الإنسان هو رفضه أن يكنز الله فوق كل شيء. والنتيجة الأولى: "حمقوا في أفكارهم"، أي صار تفكيرهم فارغا باطلا، لأن الله أعطى العقل ليعرفه ويسبحه، فإذا لم يتجه إليه صار كل استدلال فارغا ولو كان صاحبه عبقريا (١كو ٣: ٢٠). ويضرب مثل نبوخذنصر الذي تكبر ثم أذل، ولما رفع عينيه إلى السماء رجع إليه عقله فسبح الله (دا ٤: ٣٠-٣٤). والنتيجة الثانية: "أظلم قلبهم"، لأن القلب ليس فيه مصدر نور ذاتي، والنور الروحي يأتي فقط من مجد الله في وجه المسيح (مت ٦: ٢٢؛ يو ٨: ١٢؛ ١: ١٤؛ أف ١: ١٨؛ ٢كو ٤: ٦). والتطبيق أن من يستبدل مجد الله يبقى في الظلمة مهما كان ذكيا أو مشغولا.' },
  { r: '22-23', k: 'piper', ser: 'the-first-dark-exchange-idolatry', p: 'يقول بايبر إن الاستبدال يبدو حكمة لمن يقوم به: صنع الإله الخاص يبدو إبداعا واستقلالا، والرغبة الكامنة وراءه هي أن يحكم الإنسان نفسه، كما أغرت الحية حواء بأن تصير مثل الله ورأت الشجرة شهية للنظر (تك ٣: ٥-٦). لكنه في الحقيقة حماقة لسببين يذكرهما هنا. أولا، الفرق في القيمة لا نهائي: العبارة اليونانية "شبه صورة الإنسان" تعني طبقات من النسخ، والإنسان نفسه صورة الله (تك ١: ٢٧)، فهي مبادلة الأصل بنسخة عن نسخة عن نسخة. ثانيا، استبدال ما لا يفنى بما يفنى، والعشب ييبس أما كلمة الله فتثبت (إش ٤٠: ٧-٨)، كمن يبادل ماسة بخوخة منسية أو ذهبا بمسمار يصدأ. وينتقد شعار "الصورة هي كل شيء"، ويقول إن مجد الله هو كل شيء. ويستعمل قصة شراء ألاسكا سنة ١٨٦٧ التي سخر منها الناس ثم ظهرت قيمتها، ليبين أن المظاهر تخدع. والتطبيق أن نحسب كل شيء نفاية من أجل المسيح (في ٣: ٨)، فلا نبادل الله بشيء بل نبادل كل شيء به.' },
  { r: '24-25', k: 'piper', ser: 'the-other-dark-exchange-homosexuality', p: 'يرى بايبر في الآيات نمطا يتكرر ثلاث مرات: الناس يستبدلون الله بالمخلوق (٢٣، ٢٥، ٢٨)، فيسلمهم الله إلى ما فضلوه (٢٤، ٢٦، ٢٨)، فتأتي النتيجة في أجسادهم وحياتهم. والآية ٢٤ هي الدورة الأولى: أسلمهم الله في شهوات قلوبهم إلى النجاسة. ويقول إن اضطراب الجنس البشري في الجنس عموما هو دينونة من الله على استبدال ذاته بالمخلوق، وهذا يشمل كل الناس. ثم يشرح الآية ٢٥: "حق الله" هو أن الله مجيد ومشتهى فوق كل شيء، و"الكذب" هو أن المخلوق أشهى من الله. فالمشكلة الأعمق هي عبادة فاشلة قبل أن تكون سلوكا فاشلا. ويؤكد أن الشذوذ ليس الدينونة الوحيدة، فالموت والمرض والآلام كلها من ثمار السقوط (٥: ١٥-١٨؛ ٨: ٢٠-٢٣).' },
  { r: '26-27', k: 'piper', ser: 'the-other-dark-exchange-homosexuality', p: 'يقول بايبر إن الآية ٢٦ هي الدورة الثانية: أسلمهم الله إلى أهواء الهوان. ويشرح أن عبارة "خلاف الطبيعة" كانت تعبيرا شائعا في الكتابات الأخلاقية اليونانية لوصف الممارسة المثلية نفسها. ويرفض التفسير القائل إن بولس يدين فقط من كانوا بطبيعتهم مغايرين ثم مارسوا المثلية، ويقدم ثلاثة أسباب: أن الفعل "اشتعلوا" قوي جدا لا يناسب من ميله الطبيعي مغاير، وأن قراءة الازدواجية تجعل الميلين طبيعيين وهذا ما لا يقبله بولس، وأن بناء المقطع كله يفترض أن السلوك نفسه هو المشكلة. ويرى أن الرجولة والأنوثة صممتا لتصورا علاقة المسيح بالكنيسة (أف ٥: ٣١-٣٢)، والمثلية أوضح صور انكسار هذه الصورة. لكن نبرته رعوية: لا يريد أن يطرد أحدا، فالكنيسة جماعة خطاة مبررين يجاهدون معا نحو الطهارة، كما قيل لأهل كورنثوس إنهم اغتسلوا وتقدسوا وتبرروا (١كو ٦: ١١). وهدفه كنيسة يجد فيها صاحب هذا الميل قوة للتغلب عليه أو للعيش حياة عفيفة فرحة.' },
  { r: '24-28', k: 'piper', ser: 'the-other-dark-exchange-homosexuality-part-2', p: 'يكرر بايبر أن كل استبدال في الآيات ٢٣ و٢٥ و٢٨ يتبعه تسليم من الله، فتتفكك النفوس والمجتمعات، ومجد الله يجب أن يكون في المركز كالشمس بين الكواكب. ويؤكد أن لا فئة معفاة، فليس بار ولا واحد (٣: ٩-١٠)، ويربط جريمة قتل ماثيو شيبرد بالجذر نفسه: استبدال مجد الله بتعظيم الذات. ويقول إن الخليقة أخضعت للبطل على رجاء (٨: ١٨-٢٣)، والخلاص يأتي على مراحل: غفران الآن وتحرر من الخطية لاحقا (٥: ٩-١٠)، والله يحول نتائج الدينونة إلى وسائل نعمة (٨: ٢٨). ويرد على حجة الأصل الجيني: لو كان للميل أصل جسدي فهذا لا يجعله "طبيعيا" بالمعنى الكتابي، فالعدوانية والإدمان والغضب لها جذور جسدية أيضا، فنحتاج إلى معيار أعلى من الطبيعة الساقطة. ويعطي نصائح لمن عندهم هذا الميل: لا تجعله هويتك، وآمن بالمسيح وحده، وجاهد الخطية من داخل علاقة مع الله لا لكي تنالها، وعش العفة وابن صداقات سليمة. ونصائح للوالدين: اعترفوا بتقصيركم، وأحبوا وصلوا وقولوا الحق. ويختم بأن الله لم يدعنا لتجنب الصراع بل لمحبة الجميع وقول الحق بمحبة.' },
  { r: '28-31', k: 'piper', ser: 'the-perils-of-disapproving-god', p: 'يقرأ بايبر الآية ٢٨ حرفيا: "لم يستحسنوا أن يبقوا الله في معرفتهم"، أي لم يروا أنه يستحق أن يُعرف. ويحلل الآية في أربع خطوات: الجذر هو أن الناس لا يريدون الله ويطلبون تقرير مصيرهم كما في السقوط الأول؛ ثم دينونة الله بأن يرفع الضوابط العامة التي كان يمنع بها الشر (تك ٢٠: ٦) ويسلمهم إلى ما اختاروه؛ ثم يصير الذهن معطوبا لا يرى الخطية خطية؛ ثم تخرج منه قائمة الشرور. ويقول إن عمق الخطية نفسه دينونة إلهية. والقائمة في الآيات ٢٩-٣١ (واحد وعشرون شرا) عنده عينات لا تعني أن كل غير مؤمن فيه كل هذه الشرور، فالرواقيون مثل سنيكا وإبكتيتوس وماركوس أوريليوس كانوا مهذبين، لكن كل هذه الشرور تنبع من رفض الله، وكلما زاد التسليم زادت. ويستعمل صورا: نهر يخرج من نبع رفض الله، ومستنقع يغرق فيه من قفز عن صخرة مجد الله. ويلاحظ أن الفعل "أسلم" نفسه يرد في رو ٦: ١٧ حيث سُلم المؤمنون إلى صورة التعليم، فيذكر ثلاثة انقلابات: الغضب يرفع بعطية البر (١: ١٧)، والتسليم للفساد يصير تسليما للحق (٦: ١٧)، والذهن المرفوض يتجدد (١٢: ٢).' },
  { r: '32', k: 'piper', ser: 'doing-and-endorsing-evil', p: 'يرى بايبر أن الآية ٣٢ هي قاع الانحدار: الناس لا يفعلون الخطية المميتة فقط، بل يسرون بمن يفعلونها ويدفعونهم إليها، فيصيرون على المستوى الروحي كمن يساعد غيره على الانتحار. ويضرب مثلا بالشهوة التي يقول المسيح إنها زنى في القلب (مت ٥: ٢٧-٢٩؛ ١بط ٢: ١١)، ويذكر أرقاما من مقال سنة ١٩٩٧ عن صناعة الإباحية في أمريكا ليبين أن كثيرين يربحون من جر غيرهم إلى الموت الروحي. ثم يستخرج ثلاث ملاحظات: كل الناس يعرفون الله وبعض مطالبه الأخلاقية حتى بلا كتاب (١٨-١٩، ٣٢)؛ وهم بلا عذر في معاملة بعضهم بعضا، والتسليم إلى ذهن مرفوض لا ينقص ذنبهم (٢٠-٢١، ٢٨)؛ والمعرفة الأخلاقية أعمق من الوعي، لأن الحجز يحدث بسرعة لا يلاحظونها (١٨). وينقل عن تشارلز هودج أن أشد الخطاة فسادا يعرف أنه مستحق لغضب الله. والتطبيق في الكرازة: لا أحد صفحة بيضاء، فكلم الناس بثقة عن مجد الله ومطالبه، لأنهم يعرفونها في داخلهم، وصل أن يرفع الله عمى الخطية. ويجيب عن أسئلة مثل الكوارث بلوقا ١٣: ١-٥ وبسفر أيوب وبالصليب، ثم يقدم الإنجيل: ابن الله عاش كاملا ومات بدلنا، وكل من يثق به يغفر له ويحسب بارا.' },
  { r: '1', k: 'hodge', ser: 'romans-1-1-17', p: 'يقسم هودج الأصحاح إلى مقدمة عامة (١-١٧) ثم برهان أن الأمم لا يتبررون بأعمالهم (١٨-٣٢)، ويجعل الآيات ١-٧ تحية، و٨-١٧ مدخلا يكشف موضوعي الرسالة الكبيرين: طريق الخلاص، والذين يقدم لهم. وفي تغيير اسم شاول إلى بولس يزن ثلاثة آراء: أنه تكريم لسرجيوس بولس، وهذا يرفضه لأنه لا يليق بخلق بولس، أو أنه اسم أعطي عند دعوته كما سمي سمعان صفا، أو أنه اسم مزدوج يهودي وروماني كسيلا وسلوانس، ويجمع بين الرأيين الأخيرين. وكلمة "عبد" (دولوس) يفهمها بمعنى رسمي، أي خادم أو موظف عند المسيح، كما سمي يشوع وعبد الرب في إشعياء (يش ١: ١؛ إش ٤٢: ١؛ في ١: ١؛ يع ١: ١)، ويستنتج أن الخادم يخضع لسلطان المسيح وحده لا لسلطان الناس في الإيمان والواجب. و"المدعو" (كليتوس) معناه أنه لم يعين نفسه ولم يعينه بشر (غل ١: ١، ١٥). والرسول عنده من نال تكليفه من المسيح مباشرة، ورأى الرب القائم (١كو ٩: ١؛ أع ١: ٢١-٢٢)، فكان معلما ملهما معصوما له سلطان على الكنائس. و"المفرز" (أفوريزو) معناه التخصيص لمهمة معينة كما في غل ١: ١٥ وأع ١٣: ٢، لا رسامة عامة للخدمة. ويختم من ذلك في "ملاحظاته" بأن الخادم المفرز للإنجيل لا يجوز أن تزاحمه أشغال أخرى تضعف تكريسه له.' },
  { r: '2', k: 'hodge', ser: 'romans-1-1-17', p: 'يرى هودج أن الإنجيل كان موعودا به ومكشوفا جزئيا في العهد القديم، وأن هذا من أقوى براهين أصله الإلهي، ولذلك كان الرسل يحاجون دائما من الكتب (رو ٣: ٢١؛ ٤: ٣؛ لو ٢٤: ٤٤؛ أع ١٠: ٤٣). وكلمة "أنبياء" تشمل عنده كل كتبة العهد القديم، وموسى نفسه نبي، ويخالف مايَر الذي حصرها في الأنبياء من صموئيل فصاعدا، مستندا إلى أع ٣: ٢٤ وإلى عبارة "الناموس والأنبياء". و"الكتب المقدسة" هي الأسفار التي اعتبرها اليهود مقدسة لأنها من الروح القدس. ثم يناقش نحويا: هل عبارة "عن ابنه" في الآية ٣ تتعلق بكلمة "إنجيل" أم بالفعل "سبق فوعد"؟ ويختار ربطها بالوعد، لأنه لا حاجة إلى افتراض جملة اعتراضية. ويستخرج عقيدة أن الإنجيل موجود في بذرته في العهد القديم، فالعهدان رسالة واحدة.' },
  { r: '3', k: 'hodge', ser: 'romans-1-1-17', p: 'يقرر هودج أن لقب "ابنه" لقب طبيعة لا لقب وظيفة، فهو الابن الأزلي، الكلمة (يو ١: ١-١٤؛ كو ١: ١٣-١٧؛ عب ١: ٢-٦)، وتؤكد ذلك عبارات مثل "ابنه الخاص" و"الابن الوحيد" (رو ٨: ٣، ٣٢؛ يو ١: ١٤، ١٨؛ ٣: ١٦). والفعل "صار" (جينوماي) معناه هنا الولادة والمجيء إلى الوجود من جهة النسب، وكون المسيا من نسل داود أمر تنبأ به الأنبياء (إش ٩؛ إر ٢٣: ٥) وأكده العهد الجديد (يو ٧: ٤٢؛ أع ١٣: ٢٣). وعبارة "من جهة الجسد" (كاتا ساركا) تحصر النسب الداودي في طبيعته البشرية، فهي تلمح إلى أن فيه ما هو فوق البشر. و"الجسد" هنا الطبيعة الإنسانية الكاملة بجسد حقيقي ونفس عاقلة (يو ١: ١٤؛ ١تي ٣: ١٦)، لا الجسد وحده كما زعم أبوليناريوس. ومن هنا يستخرج عقيدة الطبيعتين: ابن داود حقا وابن الله حقا، ويجعل المسيح ألف الإنجيل وياءه.' },
  { r: '4', k: 'hodge', ser: 'romans-1-1-17', p: 'يزن هودج معاني الفعل "تعين" (هوريزو): يحد، أو يقرر، أو يعين في منصب، ويرفض معنى التعيين لأن البنوة ليست منصبا والمسيح ابن منذ الأزل، ويرفض لذلك ترجمة الفولجاتا "سبق فعين". فالمعنى عنده إعلاني: أظهر وبرهن أمام الناس أنه ابن الله. وعبارة "بقوة" لا يربطها بالمعجزات كما فعل ثيوفيلاكتس وثيودوريت، بل بالفعل نفسه: "برهن عليه بقوة". و"روح القداسة" يجعلها مقابلة لعبارة "من جهة الجسد"، فهي تعني طبيعته الإلهية، لا الروح القدس كما رأى كالفن، ولا حالة تمجيده، ويستند إلى ١تي ٣: ١٦ وعب ٩: ١٤. والقيامة عنده هي البرهان نفسه، لا مجرد زمن بعدها كما قال إيراسموس ولوثر، فقد أقام المسيح نفسه (يو ١٠: ١٨) وأقامه الآب (أع ١٧: ٣١). ثم يشرح الأسماء: "يسوع" مخلص (مت ١: ٢١)، و"المسيح" الممسوح نبيا وكاهنا وملكا، و"الرب" (كيريوس) هو ما ترجمت به السبعينية اسم يهوه، فالمؤمنون ملك له ملكا مطلقا.' },
  { r: '5-6', k: 'hodge', ser: 'romans-1-1-17', p: 'يرى هودج أن "نعمة ورسالة" قد تكون عبارة واحدة بمعنى "نعمة الرسالة"، أو أمرين: رضى الله في تجديد بولس ودعوته، ثم المنصب. وعبارة "الذي به" تدل على مصدر المنصب لا مجرد وسيلة، كما في غل ١: ١. وفي "إطاعة الإيمان" يعرض احتمالات المضاف إليه: طاعة هي الإيمان نفسه، أو طاعة نابعة من الإيمان، أو طاعة للإيمان بمعنى العقيدة (٢كو ١٠: ٥؛ ١بط ١: ٢٢)، ويبقي المعنى الذاتي لأنه الاستعمال المعتاد في العهد الجديد. و"في جميع الأمم" تعني أن تكليف الرسل عام لا محصور في أبرشية. و"لأجل اسمه" هي الغاية القصوى: مجد المسيح. وفي الآية ٦ يبرر بولس كتابته إلى كنيسة لم يؤسسها، و"مدعوو يسوع المسيح" عنده هم المدعوون دعوة فعالة استجابوا لها، لا الذين سمعوا الدعوة الخارجية ورفضوها (رو ٨: ٢٨؛ ١كو ١: ٢٤). ويستخرج أن الخدام عبيد للمسيح يأخذون سلطانهم منه، وغايتهم طاعة الإيمان في كل الأمم لمجد اسمه.' },
  { r: '7', k: 'hodge', ser: 'romans-1-1-17', p: 'يشرح هودج "أحباء الله" بأنهم محبوبون بالمحبة التي أحيتهم مع المسيح (أف ٢: ٤-٥)، لا مجرد مختارين من العالم كما اختير إسرائيل شعبا. و"قديسين" (هاجيوي) تعني المكرسين المفرزين لله، وتعني أيضا المطهرين أدبيا، ويتوقف عند أفعال التطهير (كاثايرو، كاثاريزو، هاجيازو) التي تشمل التكفير عن الذنب والتطهير بالروح معا (عب ٩: ١٤؛ ١يو ١: ٧). ويذكر أن بيزا يضع نقطة بعد "قديسين" فتبدأ التحية جملة جديدة. و"النعمة" رضى الله غير المستحق وعطاياه، و"السلام" هو الشالوم العبري، أي كل خير، وينقل عن كالفن أن رضى الله يأتي أولا ثم يتدفق منه الخير. والمهم عنده أن الرب يسوع المسيح يذكر مع الآب مصدرا واحدا للبركة وموضوعا للصلاة، وهذا برهان على لاهوته. ويطبق في "ملاحظاته": المسيحيون قديسون مكرسون، فلا يقدرون أن يعيشوا لأنفسهم أو للعالم دون أن يخونوا هويتهم.' },
  { r: '8', k: 'hodge', ser: 'romans-1-1-17', p: 'يلاحظ هودج أن "أولا" (بروتون من) تبدأ تعدادا لم يكمله الرسول، كما في ١كو ١١: ١٨. وعبارة "بيسوع المسيح" تتعلق بالفعل "أشكر" لا بعبارة "إلهي"، فالمسيح وسيط كل صلاة وتسبيح مقبول (رو ٧: ٢٥؛ أف ٥: ٢٠؛ كو ٣: ١٧؛ عب ١٣: ١٥؛ يو ١٤: ١٣). ويذكر أن بعض المخطوطات تقرأ "بيري" بدل "هوبر" في "من جهة جميعكم" والمعنى واحد. ولأن الله هو معطي الإيمان، كان ذيوع إيمانهم في العالم سببا للشكر لله لا لمدحهم. ومن هنا يستخرج عقيدة أن الله مصدر كل خير، وأن المسيح وسيط الصلاة. ويطبق ذلك في ملاحظاته: الفضائل عطايا، فهي تدعو إلى الشكر لا إلى الرضى عن النفس، ويرى أن بولس قدم الحق بطريقة تكسب السامعين ويجب أن يقتدي به الخدام.' },
  { r: '9-10', k: 'hodge', ser: 'romans-1-1-17', p: 'يرى هودج في قوله "الله شاهد لي" استشهادا وقورا بعلم الله بكل شيء، كما في ٢كو ١: ٢٣ وغل ١: ٢٠ وفي ١: ٨. والفعل "أعبده" (لاتريو) يدل دائما في العهد الجديد على خدمة دينية، و"بروحي" تستبعد الخدمة الخارجية غير المخلصة. و"إنجيل ابنه" يحتمل الإنجيل الذي موضوعه الابن، أو الإنجيل الذي علمه الابن، ويفضل الأول. وذكرهم "بلا انقطاع" يعني الصلاة لا مجرد التذكر، بدليل كلمة "متضرعا" في الآية ١٠ والمواضع الموازية (في ١: ٣؛ ١تس ١: ٢). وفي الآية ١٠ تعبر "عسى" (إي بوس) عن الخضوع لمشيئة الله، و"الآن مرة" (إيدي بوتي) عن شوق قديم بدا قريب التحقيق، والفعل "يتيسر" (إيفودو) في المبني للمجهول معناه أن يوفق الله الطريق. ويذكر أن بولس لم يكن قد بدأ الرحلة بعد (رو ١٥: ٢٥-٢٩)، فكانت صلاته أن تسمح الظروف بها تحت مشيئة الله. ويستخرج من ذلك الاعتراف بعناية الله في أمور الحياة العادية.' },
  { r: '11-12', k: 'hodge', ser: 'romans-1-1-17', p: 'يفسر هودج "هبة روحية" (خاريسما بنيوماتيكون) تفسيرا واسعا: ليست المواهب المعجزية في ١كو ١٢ وحدها، ولا مواهب التعليم والنبوة العادية وحدها، بل كل ثمر للروح من زيادة في المعرفة أو النعمة أو القوة. ويعترف بأن الرسل كانوا يمنحون المواهب المعجزية بوضع الأيدي (أع ٨: ١٧؛ ١٩: ٦)، وأن رومية لم تكن من تأسيس رسول، فقد يظن أن بولس أرادها، لكنه يرى أن السياق يرجح المعنى الأوسع. و"ثباتكم" (ستيريزو) زيادة في الثقة والمشاعر الدينية والعزم وقوة الطاعة (١تس ٣: ٢؛ أف ٣: ١٦). وفي الآية ١٢ يرفض هودج حصر "لنتعزى" في معنى المواساة، ويفهمها تشجيعا وتقوية متبادلة للإيمان في شركة القديسين. ويلاحظ نحويا أن صيغة المصدر تتبع جملة الغاية في الآية ١١، مع تنقل مألوف بين المضارع والمصدر (لو ١: ٥٥). ويستخرج أن الخدام يأخذون من الشعب كما يعطون، وأن الشركة المسيحية غايتها البنيان بالإيمان المشترك.' },
  { r: '13-15', k: 'hodge', ser: 'romans-1-1-17', p: 'يقول هودج إن "لست أريد أن تجهلوا" أسلوب للتأكيد، وإن قصد بولس قديم منذ سنين (رو ١٥: ٢٣). ويزن معنى "ومنعت": أهي استدراك أم جملة اعتراضية، ويرى أن المانع كان ضغط العمل الرسولي، وربما قيادة الروح كما في أع ١٦: ٦-٩. و"الثمر" هو ثمر الخدمة من تجديد وبنيان. وفي الآية ١٤ يشرح أن "البربري" معناها الأصلي الأجنبي (١كو ١٤: ١١)، فاليونانيون والبرابرة يعني كل الأمم، ورومية كانت خلاصة العالم ففيها الحكيم والجاهل. وفي الآية ١٥ يعرض ثلاث قراءات لعبارة "ما هو لي مستعد" (تو كات إمي بروثومون): "من جهتي أنا مستعد" كما عند كالفن، أو "ما في مستعد" كما عند بيزا، أو "استعدادي"، ويفضل قراءة كالفن لأنها تبرز اعتماد بولس على الله. والفعل "تبشير" يستعمل مطلقا حتى مع مسيحيين يعرفون الرسالة (رو ١٥: ٢٠). ويستخرج أن على الخادم أن يكرز للجميع، أغنياء وفقراء، حكماء وجهلاء.' },
  { r: '16', k: 'hodge', ser: 'romans-1-1-17', p: 'يرى هودج أن بولس لا يستحي برسالة يعدها الحكماء جهالة (١كو ١: ٢٣). وفي "قوة الله" يرفض أن تكون تعبيرا عبريا بمعنى "قوة عظيمة" ويراه مشكوكا فيه وغير ضروري، ويذكر قراءة بيزا "قوية إلهيا"، ويختار المعنى المعتاد: قوة مصدرها الله. والخلاص نجاة من الخطية وعقابها ودخول إلى الحياة الأبدية، وهذا لا تقدر عليه وسيلة بشرية. وفي "لكل من يؤمن" يضع التشديد على الكلمتين: "كل" تشمل اليهودي والأممي والحكيم والجاهل، و"يؤمن" تستبعد الختان والمعمودية وحفظ الناموس شرطا، فيخرج منها عقيدتان: الخلاص بالإيمان، وهو لكل الناس. ثم يحلل الإيمان إلى معرفة وتصديق واتكال، ويتتبع تراكيب الفعل والاسم مع حروف الجر المختلفة، ويقرر أن استعمال الكتاب لا التحليل الفلسفي هو ما يحدد المعنى: إدراك الحق المعلن وقبوله والاتكال عليه. و"لليهودي أولا" عنده أسبقية زمنية لا امتياز في الملاءمة (رو ٣: ٩، ٢٩؛ ١٠: ١٢)، لأن الخلاص هو من اليهود (يو ٤: ٢٢). وفي عقائده يقرر أن الإنجيل وحده يخلص، وأن حكمة البشر فشلت في ذلك على مدى آلاف السنين.' },
  { r: '17', k: 'hodge', ser: 'romans-1-1-17', p: 'يقرر هودج أن "بر الله" هنا ليس صفة الله من عدل أو صدق، لأنه "بالإيمان" و"بدون الناموس" و"عطية" (رو ٥: ١٧) و"ليس برنا" (رو ١٠: ٣؛ في ٣: ٩). ثم يعرض قولين: بر يعطيه الله كما عند بيزا، وبر يقبله الله ويرضى عنه كما عند لوثر وكالفن، ويجمع بينهما بالحسبان: بر يعطيه الله ويقبله، به يقف المؤمن مبررا أمامه. ويقارن ثلاثة مذاهب: البيلاجي الذي يجعله برا أخلاقيا بالأعمال، والروماني الذي يجعله برا داخليا تنتجه النعمة، والبروتستانتي الذي يجعله بر المسيح المحسوب لنا، وهو ما يتمسك به. وفي "بإيمان لإيمان" يزن أربعة آراء: من إيمان العهد القديم إلى إيمان الإنجيل كما عند ثيودوريت ويرفضه، والنمو في الإيمان كما عند كالفن ويشك في ملاءمته للسياق، ومعنى "بالإيمان وحده" كما عند بنجل ويراه واضحا جيدا، و"للمؤمنين" كما عند أكثر المحدثين. والاستشهاد بحبقوق ٢: ٤ يبين أن هذا هو طريق الله القديم، ويقبل تركيب "البار بالإيمان يحيا" الموافق للتنقيط العبري، والحياة هنا الحياة الروحية الأبدية. ويختم ملاحظاته بأن رفض التبرير بالإيمان رفض للإنجيل، وأن لا حكمة ولا أخلاق ولا استقامة عقيدة تنفع من لم يقبل بر الله أساسا لقبوله.' },
  { r: '18', k: 'hodge', ser: 'romans-1-18-32', p: 'يبدأ هودج القسم بتحليله: لا بد أن يبين الرسول أولا أن التبرير بالأعمال مستحيل، فيبدأ بالأمم (١: ١٨-٣٢) ثم باليهود (ص ٢؛ ٣: ١-٢٠)، فالآية تعليل للآية ١٧: لأن البشر خطاة صار التبرير بالأعمال ممتنعا. و"غضب الله" عنده عدله العقابي، لا انفعال كانفعال البشر، بل قصده الثابت أن يعاقب الخطية. والفعل "معلن" (أبوكاليبتيتاي) معناه يكشف ويعرف، ويكشف بنتائجه: العقوبات، وميل الخطية الطبيعي إلى الشقاء، وشهادة الضمير، لا بالضرورة بإعلان خاص، و"من السماء" تعني من مسكن الله. ويميز بين "الفجور" (أسيبيا) أي عدم التقوى نحو الله، و"الإثم" (أديكيا) أي الظلم نحو الناس، ويرى أن بقية الأصحاح تبرهن كلا منهما. وفي "يحجزون الحق" يزن معنيين للفعل كاتيخين: "يمتلكون" الحق مع أنهم يعيشون بالإثم، أو "يعوقون ويكبتون" كما في ٢تس ٢: ٦-٧، ويختار مع أكثر المفسرين المعنى الثاني، والإثم وسيلة هذا الكبت. وفي عقائده يجعل العدل العقابي جوهريا في طبيعة الله، وهو أساس ضرورة الكفارة.' },
  { r: '19', k: 'hodge', ser: 'romans-1-18-32', p: 'يرفض هودج ترجمة "ما يمكن معرفته عن الله"، لأن كلمة "غنوستون" في الاستعمال تعني "ما هو معروف" (أع ١: ١٩؛ ١٥: ١٨؛ تك ٢: ٩ في السبعينية). والمعرفة المقصودة ليست مجرد وجود الله بل طبيعته وصفاته، كما تبين الآيتان ٢٠ و٣٢. وعبارة "ظاهرة فيهم" تحتمل "بينهم" أو "في داخلهم"، ويفضل مع بيزا "في عقولهم"، لأن هذه المعرفة فطرية. ويرفض رأي جروتيوس الذي حصر هذه المعرفة في مدارس فلسفية كالفيثاغوريين، فالإظهار عام لكل البشر. وينقل فكرة كالفن أن الإنسان خلق ليكون متفرجا على صنعة الله في الخليقة. ومن هنا يقرر في عقائده أن الله لم يترك البشر قط بلا شاهد، فالخليقة والضمير يجعلان الفجور والإثم بلا عذر.' },
  { r: '20', k: 'hodge', ser: 'romans-1-18-32', p: 'يعرض هودج تفسيرين لكلمة "أموره غير المنظورة" (أوراتا): الخلق والعناية والأحكام كما عند ثيودوريت، أو الصلاح والحكمة والقدرة والجلال كما عند ثيوفيلاكتس، ويختار مع أكثر المحدثين رأي ثيوفيلاكتس لأن الآية نفسها تفسرها بقدرته ولاهوته. ويلاحظ أن "تي... كاي" تقسم فكرة واحدة إلى قسمين ولا تضيف فكرة جديدة، ويميز بين "ثيئوتيس" (θειότης) أي الألوهية والكمال الإلهي الظاهر، و"ثيوتيس" (θεότης) بمعنى ذات اللاهوت. و"منذ خلق العالم" تعني فعل الخلق لا المخلوق، و"ترى" (كاثوراتاي) تعني أن العقل يدرك غير المنظور بواسطة "المصنوعات" (بوييماسين). ويقرر أن هذا الإعلان يكفي ليجعل الناس بلا عذر، لكنه لا يكفي وحده ليغلب عمى الإنسان، وينقل عن كالفن أن النور كاف في ذاته لا بالنسبة لعمانا. وفي عقائده يستخرج أن الدين الطبيعي لا يخلص، فتجربة كل الأمم تشهد أنه لم يقد إلى معرفة صحيحة لله، فالإعلان الخاص ضروري. ويطبق: علينا أن نتعلم رؤية كمالات الله في أعماله.' },
  { r: '21', k: 'hodge', ser: 'romans-1-18-32', p: 'يربط هودج "لأنهم" (ديوتي) بآخر الآية ٢٠، وهو الربط الطبيعي، ويرفض ربط روكرت لها بالآية ١٨ مع افتراض فكرة محذوفة لأنه متكلف. وعبارة "لما عرفوا الله" تعني أنهم امتلكوا فعلا إعلانا مفهوما، لا مجرد فرصة للمعرفة. و"لم يمجدوه" (إدوكسازان) أي لم يكرموه ولم يعبدوه، ولم يشكروه على عطاياه. والفعل "حمقوا" (إماتايوثيسان) يدل في الكتاب على الحماقة والشر معا، ولهذا تسمى الأوثان "أباطيل" (ماتايا). وكلمة "أفكارهم" (ديالوجيسموي) تحمل في العهد الجديد غالبا معنى رديئا. و"القلب" عنده هو النفس كلها، بالعقل والعواطف معا (أف ٤: ١٧؛ مت ١٣: ١٥؛ ٢كو ٤: ٦). وفي عقائده يقرر أن الضلال في الدين والأخلاق جذره الفساد: الناس يجهلون الله لأنهم لا يريدون أن يحتفظوا به في معرفتهم. ويطبق: عقل الإنسان معرض للضلال كقلبه للخطية، فإذا ابتعد عن الله فقد الحق كما يفقد النور بعيدا عن الشمس.' },
  { r: '22-23', k: 'hodge', ser: 'romans-1-18-32', p: 'يفسر هودج "يزعمون" (فاسكونتيس) بمعنى الادعاء، فكلما زاد افتخارهم بالحكمة زادت حماقتهم. وفي الآية ٢٣ يرى أن "المجد" اسم جامع لكمالات الله. ويلاحظ أن تركيب "أبدلوا... بـ" (ألاسين إن) يتبع التعبير العبري والسبعينية في مز ١٠٦: ٢٠، فالمعنى "استبدلوا مجد الله بصورة" لا "حولوه إلى صورة". ويذكر أن الوثنية امتدت إلى صور البشر والحيوانات، وأن الوثنيين اختلفوا: بعضهم عد الصنم رمزا، وبعضهم مسكنا للإله، وبعضهم تجسيدا للوجود الكلي، لكن الكتاب يعد ذلك كله عبادة أوثان، ومنه عبادة الإله الحقيقي بواسطة الصور. والبرهان على فجور الأمم عنده هو انتشار الوثنية رغم إعلان الله نفسه في الخليقة. ويطبق: إن كانت الخطايا تحت نور الطبيعة الخافت بلا عذر، فالخطايا تحت نور الكتاب المقدس أشد جرما.' },
  { r: '24', k: 'hodge', ser: 'romans-1-18-32', p: 'يناقش هودج التركيب: الفعل "أسلمهم" (باراديدومي) يتعلق بعبارة "إلى النجاسة"، كما يتكرر التركيب نفسه في الآيتين ٢٦ و٢٨، ولا يربطه بعبارة "في شهوات قلوبهم" لأن هذا الفعل لا يأتي مع "إن" في العهد الجديد، وإن كان المعنى عندئذ مقبولا. وعبارة "لإهانة" (تو أتيمازيستاي) مصدر مع أداة تعريف في المضاف إليه يعبر عن الغاية أو النتيجة، والفعل قد يكون في صيغة الوسط أو المجهول، ويفضل المعنى التبادلي: أهانوا بعضهم بعضا، مستشهدا بكالفن عن علامات الخزي العميقة. والأهم عنده رفض القول بأن الله مجرد سامح بالخطية: اللغة تعني تخليا قضائيا، عقابا على الارتداد، فالله يرفع العناية الرادعة والنعمة ويسلم الخاطئ إلى خطيته. ويستند إلى ثولوك وإلى القول الرباني إن الخطية تجازى بالخطية، وإلى دي فيته، وينقل عن ماير أن هذا لا يجعل الناس آلات، فالحرية باقية، والعمل نفسه ينسب إلى الله وإلى الخاطئ معا (أف ٤: ١٩). وفي عقائده: الله كثيرا ما يعاقب خطية بتسليم الخاطئ لغيرها، وهذا لا يناقض قداسته لأنه لا يدفع إلى الشر بل يرفع الرادع. ويطبق: أماننا من الخطايا الفاضحة في الله لا في أنفسنا، وأشد عقاب هو أن ينزع الروح القدس.' },
  { r: '25', k: 'hodge', ser: 'romans-1-18-32', p: 'يرى هودج أن اسم الموصول "الذين" يحمل معنى التعليل: لأنهم فعلوا هذا صاروا كما يصف ما بعده. والتركيب مثل الآية ٢٣: "استبدلوا بـ" لا "حولوا إلى". و"حق الله" عنده الإله الحقيقي نفسه لا مجرد قضايا صحيحة عنه، و"الكذب" هو الإله الكاذب، فالأوثان تسمى كذبا في إر ١٣: ٢٥ و١٦: ١٩. والفعلان "اتقوا وعبدوا" متقاربان، الأول يبرز الإجلال الداخلي، والثاني الخدمة الخارجية. و"المخلوق" أي مخلوق بعينه لا الخليقة كلها. وفي "دون الخالق" يفضل معنى تجاهل الخالق وتخطيه كما عند بيزا، على معنى "أكثر من الخالق". وفي "مبارك إلى الأبد" يزن قول هارلس وماير "مسبح" وقول بريتشنايدر وثولوك "مستحق للإكرام"، ويرى أن الكلمة تصف الله بأنه الموضوع الحقيقي للتسبيح، و"آمين" تأكيد عبري يعلن به بولس موافقته.' },
  { r: '26-27', k: 'hodge', ser: 'romans-1-18-32', p: 'يرى هودج أن الآية ٢٦ توسيع للآية ٢٤، وأن "أهواء الهوان" هي خطايا النجاسة. ويعطي أربعة أسباب لذكر هذه الخطايا أولا: ارتباطها بالوثنية وعباداتها، وأن الابتعاد عن الله يقود طبيعيا إلى الشهوانية، وأنها مذلة بشكل خاص، وأنها كانت أكثر جرائم العالم الوثني علانية وانتشارا. والفساد شمل كل الطبقات وكلا الجنسين، ويشير إلى أن الكتاب الوثنيين أنفسهم يشهدون بذلك. ويرى أن النساء ذكرن أولا لأنهن آخر من يتأثر عند انحطاط الأخلاق، ففسادهن علامة على زوال الفضيلة كليا. وفي الآية ٢٧ يرى عبارة "نائلين في أنفسهم جزاء ضلالهم" المرة الثالثة التي يقرر فيها الرسول أن الانحطاط الأدبي عقاب على الارتداد، و"الضلال" هو ترك الإله الحقيقي، و"الجزاء" هو هذا الانحطاط نفسه. ويطبق: خطايا النجاسة مذلة بشكل خاص، والحفظ منها علامة رضى إلهي، والتسليم لها علامة رفض (جا ٧: ٢٦؛ أم ٢٢: ١٤).' },
  { r: '28', k: 'hodge', ser: 'romans-1-18-32', p: 'يلاحظ هودج أن الوثنيين أنفسهم أدركوا الصلة بين عدم التقوى والرذيلة، ويذكر شيشرون وسيليوس إيتاليكوس، ويقول إن من يفصلون الدين عن الأخلاق أجهل من الوثنيين ويستثيرون غضب الله. والتركيب "كما... كذلك أسلمهم الله" مقابلة مقصودة. والفعل "لم يستحسنوا" (أوك إدوكيماسان) معناه امتحنوا ورأوا أن الأمر لا يستحق، أي حسبوا الاحتفاظ بالله غير جدير (١كو ١٦: ٣؛ ١تس ٢: ٤). و"أن يبقوا الله في معرفتهم" (إخين إن إبيجنوسي) أقوى من مجرد المعرفة، فهي معرفة دقيقة عملية. وفي "ذهن مرفوض" (أدوكيموس) يرفض قول بيزا وبنجل إنه "ذهن عاجز عن التمييز"، ويحتج بالاشتقاق: "دوكيموس" المقبول بعد الامتحان، فـ"أدوكيموس" المرفوض، فهناك تلاعب لفظي مقصود: لم يستحسنوا الله فأسلمهم إلى ذهن غير مستحسن. والمصدر "ليفعلوا" تفسيري يعبر عن نتيجة التخلي. وفي عقائده: الدين هو الأساس الوحيد الحقيقي للأخلاق، وعدم التقوى والفساد الأدبي مرتبطان لا ينفصلان.' },
  { r: '29-31', k: 'hodge', ser: 'romans-1-18-32', p: 'يربط هودج اسم الفاعل "مملوئين" بالضمير في الآية ٢٨ وبالمصدر "ليفعلوا"، لا بالفعل "أسلمهم"، ويشدد على أن هذه الرذائل نتيجة التخلي الإلهي لا شيء سابق عليه. ويقول إن هذه الجرائم كانت شائعة، وكثيرا ما بررت أو مدحت، ويشير إلى أن الكتاب اليونانيين واللاتينيين يصفون الفساد نفسه، ويذكر سينيكا في كتابه عن الغضب. ويمر على القائمة: الزنا والشر والطمع والخبث، والحسد والقتل المقترنين بالجرس أو بالسبب، والخصام والمكر (دولوس، وأصلها الطعم في الصيد)، والسوء، والنمامين، والمفترين. وفي "مبغضين لله" (ثيوستيجيس) يلاحظ أن الاستعمال يرجح المعنى المجهول "مكروهين من الله" بينما السياق يرجح المعنى الفاعل "كارهين لله"، ويرفض محاولة ماير جعلها صفة لما قبلها، ويذكر أن أكثر المفسرين يأخذون المعنى الفاعل. والكبرياء تظهر عنده في ثلاث كلمات: الثالبين المتعجرفين، والمتعظمين، والمدعين. وذكر "غير طائعين للوالدين" وسط هذه الجرائم يبين مدى جدية العصيان للوالدين في نظر الكتاب. وكلمات الآية ٣١ بأداة النفي تصف أناسا بلا فهم ولا وفاء بالعهد ولا حنو طبيعي ولا مصالحة ولا رحمة.' },
  { r: '32', k: 'hodge', ser: 'romans-1-18-32', p: 'يشرح هودج أن "حكم الله" هو قضاؤه العادل بأن فاعلي هذه يستحقون الموت، و"الموت" عنده بالمعنى الواسع: العقاب. وهذه المعرفة مكتوبة في القلب ولازمة لكون الإنسان كائنا أدبيا، ويحيل إلى برهان الأصحاح التالي عن الناموس المكتوب في القلوب. ويقرر أن التخلي القضائي لا يلغي المسؤولية، لأن النهر الفاسد ينبع من الداخل، من طبيعتهم هم. وأعمق الانحطاط ليس ارتكاب الخطايا فقط، بل الرضى عن فاعليها. وفي عقائده: تشجيع جرائم الآخرين والتلذذ بها أشد فسادا من ارتكابها، وحتى أشد الناس فسادا يحتفظون بمعرفة تعرضهم لغضب الله، فالضمير لا ينطفئ تماما، وكون الخطية تستحق العقاب بديهية يعترف بها الحس الأدبي. ويختم ملاحظاته: الخطية بلا عذر فلا نبررها بل نطلب النجاة من عقابها، ولأن نور الطبيعة لا يقود الوثنيين إلى الله، فإرسال الكتاب المقدس إليهم واجب ملح، والتلذذ بالأبرار يجعلنا أفضل بينما التلذذ بالأشرار أضمن طريق للانحدار تحتهم.' },
];
